/* ===================== BÀI 16 · Logic, TEST, shift và rotate ===================== */
/* Bài 16 · Logic, TEST, shift và rotate (AMTS-EMB-002-M04-L04, X86-016) — sinh bởi tools/author/mpu8086/l16.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P16=[{"label": "Ví dụ: AND xóa, OR đặt, XOR đảo bit", "code": "; Ví dụ 1: AND xóa bit, OR đặt bit, XOR đảo bit\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AL, 'q'                 ; 71h = 0111 0001\n        AND     AL, 0DFH                ; xóa bit 5: 51h = 'Q'\n        MOV     DL, AL\n        MOV     AH, 02H\n        INT     21H                     ; in Q\n        OR      DL, 20H                 ; đặt bit 5: 'q'\n        INT     21H\n        XOR     DL, 20H                 ; đảo bit 5: 'Q'\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bit 5 phân biệt chữ hoa và chữ thường trong ASCII. AND AL, 0DFh xóa bit 5: 'q' (71h) thành 'Q' (51h). OR DL, 20h đặt lại bit 5: 'q'. XOR DL, 20h đảo bit 5: 'Q'. Màn hình in QqQ. Xem CF, OF luôn 0 sau ba lệnh logic. Đoán trước: sau AND AL, 0DFh, AL bằng bao nhiêu (hệ 16)? Đáp án 51h."}, {"label": "Ví dụ: TEST đọc bit, không đổi dữ liệu", "code": "; Ví dụ 2: TEST đọc một bit mà không đổi dữ liệu\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ngiu     DB      ?                       ; AL sau hai lệnh TEST\nz1      DB      ?                       ; ZF sau TEST AL, 04h (bit 6 của AH)\nz2      DB      ?                       ; ZF sau TEST AL, 08h\nhuy     DB      ?                       ; AL sau AND AL, 08h\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AL, 0A5H                ; 1010 0101\n        TEST    AL, 04H                 ; bit 2 = 1 → ZF = 0\n        LAHF                            ; AH = SF ZF - AF - PF - CF\n        AND     AH, 40H                 ; chỉ giữ ZF (bit 6)\n        MOV     z1, AH\n        TEST    AL, 08H                 ; bit 3 = 0 → ZF = 1\n        LAHF\n        AND     AH, 40H\n        MOV     z2, AH\n        MOV     giu, AL                 ; AL vẫn A5h\n        AND     AL, 08H                 ; AND ghi kết quả: AL = 00h\n        MOV     huy, AL\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "AL = A5h = 1010 0101. TEST AL, 04h: bit 2 bằng 1 nên ZF = 0 (z1 = 00h); TEST AL, 08h: bit 3 bằng 0 nên ZF = 1 (z2 = 40h, bit 6 của AH sau LAHF). AL vẫn A5h (giu). AND AL, 08h cho cùng ZF nhưng ghi AL = 00h (huy): dữ liệu bị mất. Đoán trước: sau TEST AL, 08h, AL bằng bao nhiêu? Đáp án A5h."}, {"label": "Lỗi: SHL AX, 3 không có trên 8086", "code": "; Ví dụ 3 (lỗi cố ý): dịch 3 bit bằng số tức thời\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AX, 5\n        SHL     AX, 3                   ; chỉ có từ 80186\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi dịch cố ý: 8086 chỉ dịch 1 bit hoặc CL bit. SHL AX, 3 có từ 80186. Sửa: MOV CL, 3 rồi SHL AX, CL, hoặc viết SHL AX, 1 ba lần (nhanh hơn, xem mục 16.4)."}, {"label": "Ví dụ: SHL, SHR, SAR và lũy thừa của 2", "code": "; Ví dụ 4: SHL, SHR, SAR nhân chia lũy thừa của 2\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nkq1     DW      ?\nkq2     DW      ?\nkq3     DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, 25\n        SHL     AX, 1                   ; × 2 = 50\n        MOV     CL, 3\n        SHL     AX, CL                  ; × 8 = 400\n        MOV     kq1, AX\n        MOV     AX, -100                ; FF9Ch\n        MOV     BX, AX\n        SHR     AX, 1                   ; đẩy 0 vào bit 15: 7FCEh\n        SAR     BX, 1                   ; giữ bit dấu: FFCEh = -50\n        MOV     kq2, AX\n        MOV     kq3, BX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "SHL AX, 1 nhân 2 (25 → 50); MOV CL, 3 / SHL AX, CL nhân 8 (50 → 400) với 8 + 4 × 3 = 20 chu kỳ. Với −100 (FF9Ch): SHR đẩy 0 vào bit 15 cho 7FCEh = 32 718 (sai nếu hiểu là số có dấu), SAR giữ bit dấu cho FFCEh = −50. Đoán trước: sau SAR BX, 1, BX bằng bao nhiêu? Đáp án FFCEh."}, {"label": "Bẫy: SAR làm tròn xuống, khác IDIV", "code": "; Ví dụ 5 (bẫy): SAR làm tròn xuống, IDIV về 0\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nkqsar   DW      ?\nkqidiv  DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, -7\n        SAR     AX, 1                   ; -7 / 2 làm tròn xuống: -4\n        MOV     kqsar, AX\n        MOV     AX, -7\n        CWD\n        MOV     BX, 2\n        IDIV    BX                      ; -7 / 2 cắt về 0: -3\n        MOV     kqidiv, AX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bẫy cố ý: cả hai cách “chia −7 cho 2”. SAR làm tròn xuống: −3,5 → −4 (FFFCh). IDIV cắt về 0: −3 (FFFDh), số dư −1. Muốn kết quả giống phép chia của ngôn ngữ C khi số âm, dùng IDIV (chậm) hoặc cộng 1 trước khi SAR khi số âm. Đoán trước: sau SAR AX, 1, AX bằng bao nhiêu? Đáp án FFFCh."}, {"label": "Ví dụ: dịch 32 bit qua CF, quay nửa byte", "code": "; Ví dụ 6: dịch 32 bit qua CF; ROL đổi hai nửa byte\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nthap    DW      ?\ncao     DW      ?\nnib     DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, 8000H\n        MOV     DX, 0001H               ; DX:AX = 0001 8000h\n        SHL     AX, 1                   ; AX = 0000h, CF = 1 (bit 15 cũ)\n        RCL     DX, 1                   ; DX = 0002h + CF = 0003h\n        MOV     thap, AX\n        MOV     cao, DX                 ; DX:AX = 0003 0000h = × 2\n        MOV     AL, 3CH\n        MOV     CL, 4\n        ROL     AL, CL                  ; quay 4 bit: C3h\n        MOV     nib, AL\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "SHL AX, 1 đẩy bit 15 của AX (bằng 1) ra CF; RCL DX, 1 đưa CF vào bit 0 của DX: DX:AX từ 0001 8000h thành 0003 0000h, đúng bằng nhân 2 số 32 bit. ROL AL, CL với CL = 4 đổi chỗ hai nửa byte: 3Ch → C3h (8 + 4 × 4 = 24 chu kỳ). Đoán trước: ngay sau SHL AX, 1, CF bằng bao nhiêu? Đáp án 1."}, {"label": "Ví dụ: nhân 10 bằng dịch và cộng", "code": "; Ví dụ 7: nhân 10 bằng dịch và cộng, so với MUL\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nso      DW      1234\nkq1     DW      ?                       ; bằng MUL\nkq2     DW      ?                       ; bằng dịch và cộng\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, so\n        MOV     BX, 10\n        MUL     BX                      ; ít nhất 118 chu kỳ\n        MOV     kq1, AX\n        MOV     AX, so\n        SHL     AX, 1                   ; × 2\n        MOV     BX, AX                  ; BX = so × 2\n        SHL     AX, 1                   ; × 4\n        SHL     AX, 1                   ; × 8\n        ADD     AX, BX                  ; × 8 + × 2 = × 10\n        MOV     kq2, AX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Cùng kết quả 12 340 (3034h). Cách MUL: 4 + 118 = 122 chu kỳ chỉ cho hai lệnh MOV BX, 10 / MUL BX (118 là cận dưới). Cách dịch và cộng: 2 + 2 + 2 + 2 + 3 = 11 chu kỳ. Xem cột chu kỳ ở phần Mã máy và chu kỳ. Đoán trước: ngay trước ADD AX, BX, AX bằng bao nhiêu (hệ 10)? Đáp án 9872 (1234 × 8)."}];
const sim16=makeX86Sim(document.getElementById("x86-l16"),{id:"s16",presets:P16,file:"BAI16.ASM"});
makeX86Ex(document.getElementById("ex-l16"),sim16,[{"t": "Bit 3 của phím", "d": "Đọc một phím bằng INT 21h hàm 08h. Ghi bit 3 của mã ASCII (0 hoặc 1) vào biến byte bit, rồi in chữ số đó ('0' hoặc '1') bằng INT 21h hàm 02h. Chưa dùng lệnh nhảy: làm bằng mặt nạ và dịch bit. Kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 1: bit 3 của mã phím\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nbit     DB      ?                       ; bit 3 của mã phím: 0 hoặc 1\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H\n        INT     21H                     ; AL = mã phím\n; Viết code ở đây: bit = bit 3 của AL (0 hoặc 1),\n; rồi in '0' hoặc '1' bằng INT 21h hàm 02h\n\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "A", "out": "0", "mem": [{"at": "bit", "bytes": [0]}]}, {"in": "H", "out": "1", "mem": [{"at": "bit", "bytes": [1]}]}, {"in": "8", "out": "1", "mem": [{"at": "bit", "bytes": [1]}]}, {"in": " ", "out": "0", "mem": [{"at": "bit", "bytes": [0]}]}, {"in": "~", "out": "1", "mem": [{"at": "bit", "bytes": [1]}]}, {"in": "0", "out": "0", "mem": [{"at": "bit", "bytes": [0]}]}]}, {"t": "In 8 bit của phím", "d": "Đọc một phím bằng INT 21h hàm 08h và in mã ASCII của nó dạng nhị phân 8 chữ số, bit 7 trước (ví dụ phím A in 01000001). Code mẫu đã có vòng LOOP 8 lần in DL; viết phần đổi DL thành '0' hoặc '1'. Không dùng lệnh nhảy có điều kiện. Kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 2: in 8 bit của mã phím\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AH, 08H\n        INT     21H\n        MOV     BL, AL                  ; BL = mã phím\n        MOV     CX, 8\n        MOV     AH, 02H\nlap:\n        MOV     DL, '0'\n; Viết code ở đây: lấy bit cao nhất còn lại của BL,\n; đổi DL thành '0' hoặc '1'\n        INT     21H\n        LOOP    lap\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "A", "out": "01000001"}, {"in": " ", "out": "00100000"}, {"in": "~", "out": "01111110"}, {"in": "0", "out": "00110000"}, {"in": "U", "out": "01010101"}, {"in": "*", "out": "00101010"}]}, {"t": "Nhân 20 không dùng MUL", "d": "Đọc 4 phím bằng INT 21h hàm 08h và ghi vào biến word tong giá trị 20 × (tổng mã ASCII của 4 phím). Code mẫu đúng nhưng mỗi phím một lần MUL. Viết lại để đạt cả giới hạn chu kỳ và giới hạn số byte mã. Không in gì; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 3: 20 lần tổng mã của 4 phím\n; Bản này đúng nhưng chậm: mỗi phím một lần MUL.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ntong    DW      ?                       ; 20 × (tổng mã 4 phím)\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     tong, 0\n        MOV     CX, 4\ndoc:\n        MOV     AH, 08H\n        INT     21H\n        MOV     AH, 0                   ; AX = mã phím\n        MOV     BX, 20\n        MUL     BX                      ; AX = mã × 20\n        ADD     tong, AX\n        LOOP    doc\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "AAAA", "mem": [{"at": "tong", "word": 5200}]}, {"in": "    ", "mem": [{"at": "tong", "word": 2560}]}, {"in": "~~~~", "mem": [{"at": "tong", "word": 10080}]}, {"in": "0123", "mem": [{"at": "tong", "word": 3960}]}, {"in": "zZ!~", "mem": [{"at": "tong", "word": 7420}]}, {"in": "a b ", "mem": [{"at": "tong", "word": 5180}]}], "perf": {"cycles": 410, "bytes": 44}}]);

makeQuiz("quiz16","score16",[{"q": "AL = 5Ah (0101 1010). Sau lệnh <code>AND AL, 0Fh<\/code>, AL và CF bằng bao nhiêu?", "o": ["AL = 5Fh, CF = 0", "AL = 50h, CF = 1", "AL = 0Ah, CF giữ giá trị cũ", "AL = 0Ah, CF = 0"], "a": 3, "e": "AND với 0000 1111 giữ 4 bit thấp (1010 = Ah) và xóa 4 bit cao. AND luôn xóa CF và OF."}, {"q": "Cần biết bit 7 của AL có bằng 1 không mà vẫn giữ nguyên AL để dùng tiếp. Lệnh nào phù hợp?", "o": ["<code>AND AL, 80h<\/code>", "<code>TEST AL, 80h<\/code>", "<code>OR AL, 80h<\/code>", "<code>XOR AL, 80h<\/code>"], "a": 1, "e": "TEST đặt ZF như AND (ZF = 0 khi bit 7 bằng 1) nhưng không ghi kết quả. AND ghi đè AL; OR và XOR làm đổi bit 7."}, {"q": "Cách viết nào dịch AX sang trái 4 bit và dịch được trên 8086?", "o": ["<code>MOV CL, 4<\/code> / <code>SHL AX, CL<\/code>", "<code>SHL AX, 4<\/code>", "<code>MOV CX, 4<\/code> / <code>SHL AX, CX<\/code>", "<code>SHL AX, 1, 4<\/code>"], "a": 0, "e": "8086 chỉ có số lần dịch là 1 hoặc CL. SHL AX, 4 có từ 80186; số lần không lấy từ CX."}, {"q": "AX = FFF9h (−7). Sau <code>SAR AX, 1<\/code>, AX bằng bao nhiêu?", "o": ["FFFDh (−3)", "FFFCh (−4)", "7FFCh (32 764)", "FFF8h (−8)"], "a": 1, "e": "SAR dịch phải và chép bit dấu: 1111 1111 1111 1001 → 1111 1111 1111 1100 = −4. SAR làm tròn xuống; IDIV cho −3. 7FFCh là kết quả của SHR."}, {"q": "Cần nhân AX với 4 (biết kết quả vừa 16 bit). Cách nào ít chu kỳ nhất?", "o": ["<code>ADD AX, AX<\/code> / <code>ADD AX, AX<\/code>", "<code>MOV CL, 2<\/code> / <code>SHL AX, CL<\/code>", "<code>MOV BX, 4<\/code> / <code>MUL BX<\/code>", "<code>SHL AX, 1<\/code> / <code>SHL AX, 1<\/code>"], "a": 3, "e": "2 + 2 = 4 chu kỳ. ADD AX, AX hai lần đúng nhưng 3 + 3 = 6; MOV CL, 2 / SHL AX, CL là 4 + 8 + 8 = 20; MUL ít nhất 4 + 118."}]);

